let counter = 0

export const n5ChaptersB: LangVocabChapter[] = drafts.map((d) => ({
  id: d.id,
  emoji: d.emoji,
  titleTh: d.titleTh,
  description: d.description,
  words: d.rows.map(
    ([word, reading, romaji, pos, meaningTh, mnemonicTh, example, exampleReading, exampleTh]): LangWord => {
      counter += 1
      return {
        id: `n5b-${counter}`,
        word,
        reading,
        romaji,
        pos,
        meaningTh,
        mnemonicTh,
        example,
        exampleReading,
        exampleTh,
      }
    },
  ),
}))
